export interface StartAIQuestion {
  key: string;
  label: string;
  placeholder: string;
  type?: string;
}

const AI_QUESTIONS_BASIC: StartAIQuestion[] = DETAIL_INPUT_FIELDS.map(
  ({ name, label, placeholder }, index) => ({
    key: String(index + 1),
    label,
    placeholder,
    type: BUSINESS_AI_FIELD_TYPE_MAP[name]
  })
);

