export const getStartAIQuestions = (
  promptProfile: DraftPromptProfile
): StartAIQuestion[] =>
  promptProfile === 'rnd_plan'
    ? AI_QUESTIONS_RND
    : promptProfile === 'everyone_startup'
    ? AI_QUESTIONS_EVERYONE_STARTUP
    : AI_QUESTIONS_BASIC;

export const getStartAIReviewerTotalLength = ({
  answers,
  promptProfile
}: {
  answers: Record<string, string>;
  promptProfile: DraftPromptProfile;
}) =>
  getTotalTextLength(
    getStartAIQuestions(promptProfile).map(
      ({ key }) => answers[key] ?? ''
    )
  );
